### The Server Code

```
from mcp.server.fastmcp import FastMCP
import json
import random
from datetime import datetime, timedelta
# — Create the MCP server ---
mcp = FastMCP("weather-service")
# — Mock weather data ---
WEATHER_DATABASE: dict[str, dict] = {
"new york": {
"city": "New York",
"temperature": 5,
"unit": "celsius",
"condition": "Partly Cloudy",
"humidity": 62,
"wind_speed": 18,
},
"london": {
"city": "London",
"temperature": 8,
"unit": "celsius",
"condition": "Overcast",
"humidity": 78,
"wind_speed": 12,
},
"tokyo": {
"city": "Tokyo",
"temperature": 14,
"unit": "celsius",
"condition": "Clear",
"humidity": 45,
"wind_speed": 8,
},
"sydney": {
"city": "Sydney",
"temperature": 26,
"unit": "celsius",
"condition": "Sunny",
"humidity": 55,
"wind_speed": 15,
},
"paris": {
"city": "Paris",
"temperature": 7,
"unit": "celsius",
"condition": "Light Rain",
"humidity": 82,
"wind_speed": 10,
},
}
VALID_UNITS = ("celsius", "fahrenheit", "kelvin")
# — Temperature conversion helper ---
def convert_temp(value: float, from_unit: str, to_unit: str) -> float:
"""Convert temperature between Celsius, Fahrenheit, and Kelvin."""
# Normalize to Celsius first
if from_unit == "fahrenheit":
celsius = (value - 32) * 5 / 9
elif from_unit == "kelvin":
celsius = value - 273.15
else:
celsius = value
# Convert from Celsius to target
if to_unit == "fahrenheit":
return round(celsius * 9 / 5 + 32, 2)
elif to_unit == "kelvin":
return round(celsius + 273.15, 2)
else:
return round(celsius, 2)
# — Register tools ---
@mcp.tool()
def get_current_weather(city: str) -> str:
"""Get the current weather conditions for a city.
Args:
city: City name (e.g., 'London', 'New York')
"""
data = WEATHER_DATABASE.get(city.lower())
if not data:
available = ", ".join(d["city"] for d in WEATHER_DATABASE.values())
return f'City "{city}" not found. Available cities: {available}'
return json.dumps(
{
"city": data["city"],
"temperature": f"{data['temperature']}°C",
"condition": data["condition"],
"humidity": f"{data['humidity']}%",
"windSpeed": f"{data['wind_speed']} km/h",
},
indent=2,
)
@mcp.tool()
def get_forecast(city: str, days: int = 3) -> str:
"""Get a multi-day weather forecast for a city.
Args:
city: City name
days: Number of forecast days (1-7, default 3)
"""
days = max(1, min(7, days))
data = WEATHER_DATABASE.get(city.lower())
if not data:
available = ", ".join(d["city"] for d in WEATHER_DATABASE.values())
return f'City "{city}" not found. Available cities: {available}'
forecast = []
for i in range(1, days + 1):
date = datetime.now() + timedelta(days=i)
temp_variation = round(random.uniform(-3, 3))
humidity_variation = round(random.uniform(-5, 5))
forecast.append(
{
"date": date.strftime("%Y-%m-%d"),
"temperature": f"{data['temperature'] + temp_variation}°C",
"condition": data["condition"],
"humidity": f"{data['humidity'] + humidity_variation}%",
}
)
return json.dumps({"city": data["city"], "forecast": forecast}, indent=2)
@mcp.tool()
def convert_temperature(value: float, from_unit: str, to_unit: str) -> str:
"""Convert a temperature between Celsius, Fahrenheit, and Kelvin.
Args:
value: Temperature value to convert
from_unit: Source unit (celsius, fahrenheit, or kelvin)
to_unit: Target unit (celsius, fahrenheit, or kelvin)
"""
if from_unit not in VALID_UNITS or to_unit not in VALID_UNITS:
return f"Invalid unit. Use one of: {', '.join(VALID_UNITS)}"
result = convert_temp(value, from_unit, to_unit)
return f"{value}° {from_unit} = {result}° {to_unit}"
# — Register a resource ---
@mcp.resource("weather://cities")
def list_supported_cities() -> str:
"""List of cities with available weather data."""
cities = [
{"name": d["city"], "currentCondition": d["condition"]}
for d in WEATHER_DATABASE.values()
]
return json.dumps(cities, indent=2)
# — Start the server ---
if __name__ == "__main__":
mcp.run(transport="stdio")
```


### Python vs. TypeScript: What's Different

The Python version is noticeably shorter, and that's by design. FastMCP (which is built into the official `mcp`

package) uses Python's type hints and docstrings to auto-generate the tool schemas. Where TypeScript needs an explicit Zod schema with `.describe()`

calls, Python infers parameter types from annotations and reads the `Args:`

section of the docstring for descriptions.

The `@mcp.tool()`

decorator does the heavy lifting. It inspects the function signature, builds the JSON Schema, and registers everything with the server. The `@mcp.resource()`

decorator works the same way for resources — you just pass the URI.

Both versions produce identical MCP-compatible servers. A client can't tell which language the server is written in. That's the whole point of a protocol.

